css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::before { content: ''; position: absolute; bottom: 6%; left: 5%; width: 8%; height: 44%; border-radius: 3px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 30%, var(--accent-2))); }
.loader::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 6%; background: repeating-linear-gradient(90deg, #94a3b8 0 9%, transparent 9% 18%); }
.loader .arm { position: absolute; bottom: 36%; left: 11%; width: 52%; height: 7%; border-radius: 2px; transform-origin: left center; background: repeating-linear-gradient(90deg, var(--accent) 0 11%, #f8fafc 11% 22%); animation: gate calc(var(--loader-speed) * 3) ease-in-out infinite; }
@keyframes gate { 0%, 12% { transform: rotate(-78deg); } 38%, 62% { transform: rotate(0deg); } 88%, 100% { transform: rotate(-78deg); } }
